ALTER TABLE "pricing"."fee_schedule_revisions" ADD COLUMN "command_fingerprint" text NOT NULL;--> statement-breakpoint
ALTER TABLE "pricing"."fees" DROP CONSTRAINT "pricing_fees_identity_uk";--> statement-breakpoint
ALTER TABLE "pricing"."fees" ADD CONSTRAINT "pricing_fees_identity_uk" UNIQUE NULLS NOT DISTINCT("tenant_id","legal_entity_id","family","variant_ref","channel_id","market_id","calculation_basis","basis_quantity","unit_ref","currency_code","monetary_boundary");--> statement-breakpoint
ALTER TABLE "pricing"."fee_schedule_revisions" ADD CONSTRAINT "pricing_fee_schedule_revisions_command_fingerprint_ck" CHECK ("command_fingerprint" ~ '^[0-9a-f]{64}$');--> statement-breakpoint
ALTER TABLE "pricing"."fees" DROP CONSTRAINT "pricing_fees_variant_ck", ADD CONSTRAINT "pricing_fees_variant_ck" CHECK (jsonb_typeof("product_ref") = 'object' and "product_ref" = jsonb_build_object('moduleId', 'commerce.catalog', 'resourceId', (("product_ref"->>'resourceId')::uuid)::text, 'resourceType', 'commerce.catalog.product', 'tenantId', "tenant_id"::text) and jsonb_typeof("variant_ref") = 'object' and "variant_ref" = jsonb_build_object('moduleId', 'commerce.catalog', 'resourceId', (("variant_ref"->>'resourceId')::uuid)::text, 'resourceType', 'commerce.catalog.variant', 'tenantId', "tenant_id"::text));--> statement-breakpoint
ALTER TABLE "pricing"."fees" DROP CONSTRAINT "pricing_fees_scope_ck", ADD CONSTRAINT "pricing_fees_scope_ck" CHECK ("channel_id" in ('B2C', 'B2B') and "market_id" = btrim("market_id") and length("market_id") between 1 and 300 and "market_id" <> '*');--> statement-breakpoint
ALTER TABLE "pricing"."fees" DROP CONSTRAINT "pricing_fees_basis_ck", ADD CONSTRAINT "pricing_fees_basis_ck" CHECK (("calculation_basis" = 'FIXED_PER_LINE' and "basis_quantity" is null and "unit_ref" is null) or ("calculation_basis" = 'FIXED_PER_UNIT' and "basis_quantity" > 0 and jsonb_typeof("unit_ref") = 'object' and "unit_ref" = jsonb_build_object('moduleId', 'commerce.catalog', 'resourceId', (("unit_ref"->>'resourceId')::uuid)::text, 'resourceType', 'commerce.catalog.product-unit', 'tenantId', "tenant_id"::text)));